# --- Etapa 1: Builder ---
# Usamos una imagen de Node.js para construir la aplicación.
FROM node:18-alpine AS builder

# Establecemos el directorio de trabajo dentro del contenedor
WORKDIR /app

# Copiamos package.json y package-lock.json (o pnpm-lock.yaml si usas pnpm)
COPY package*.json ./
# Si usas pnpm, descomenta la siguiente línea y comenta la de npm
# COPY pnpm-lock.yaml ./
# RUN npm install -g pnpm

# Instalamos las dependencias con configuración más robusta
RUN npm config set fetch-timeout 300000 && \
    npm config set fetch-retries 5 && \
    npm install
# Si usas pnpm: RUN pnpm install

# Copiamos el resto del código de la aplicación
COPY . .

# Construimos la aplicación para producción.
# NEXT_PUBLIC_API_URL es una variable de entorno que pasaremos desde docker-compose.
# Esto le dice a Next.js cuál es la URL de tu backend.
ARG NEXT_PUBLIC_API_URL
ENV NEXT_PUBLIC_API_URL=${NEXT_PUBLIC_API_URL}

RUN npm run build

# --- Etapa 2: Runner ---
# Usamos una imagen más ligera para ejecutar la aplicación ya construida.
FROM node:18-alpine AS runner

WORKDIR /app

# Copiamos solo los archivos necesarios de la etapa 'builder'
COPY --from=builder /app/public ./public
COPY --from=builder /app/.next ./.next
COPY --from=builder /app/node_modules ./node_modules
COPY --from=builder /app/package.json ./package.json

# Exponemos el puerto 3000 (el puerto por defecto de Next.js)
EXPOSE 3000

# El comando para iniciar el servidor de Next.js en modo desarrollo
# El comando para iniciar el servidor de Next.js en modo desarrollo
# Agregamos un script que muestre las URLs correctas
CMD ["sh", "-c", "echo '🌐 Frontend disponible en:' && echo '  📍 Local: http://localhost:8880' && echo '  🌍 Público: https://kognitoai.cloud' && echo '  🔧 API Local: http://localhost:8889' && echo '  🔧 API Pública: https://apibase.cuerpolibre.cl' && echo '' && npm run dev"]
---
# En: nginx.conf

server {
    # Nginx escuchará en el puerto 80 DENTRO del contenedor.
    # Mapearemos este puerto al que queramos en docker-compose.
    listen 80;
    listen 443 ssl;
    server_name _; # Acepta cualquier nombre de host

    # Configuración SSL
    ssl_certificate /etc/nginx/certs/kognito.crt;
    ssl_certificate_key /etc/nginx/certs/kognito.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # --- CABECERAS DE SEGURIDAD ---
    # HSTS (Strict Transport Security) - 1 año
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    # Prevenir clickjacking
    add_header X-Frame-Options "SAMEORIGIN" always;
    # Prevenir sniffing de MIME types
    add_header X-Content-Type-Options "nosniff" always;
    # Habilitar filtro XSS del navegador
    add_header X-XSS-Protection "1; mode=block" always;
    # Controlar información de referencia
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    # CSP Básica (ajustar si es necesario para scripts externos)
    add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval' https://telegram.org; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: https://telegram.org; font-src 'self' https://fonts.gstatic.com; connect-src 'self' https://apibase.cuerpolibre.cl; frame-ancestors 'self';" always;


    # Configuración para Cloudflare
    # Aumentar tamaño de subida para evitar errores 413 con Cloudflare
    client_max_body_size 100M;

    # Redirección de HTTP a HTTPS (Compatible con Cloudflare)
    # Si Cloudflare nos contacta por HTTP (flexible SSL) o pasa la petición original
    if ($http_x_forwarded_proto = "http") {
        return 301 https://$host$request_uri;
    }

    # --- REDIRECCIONES DE SERVICE DISCOVERY (CALDAV / CARDDAV) ---
    # Permite que los clientes encuentren la API automáticamente.
    location /.well-known/caldav {
        return 301 https://$host/api/caldav/;
    }
    location /.well-known/carddav {
        return 301 https://$host/api/caldav/; # CardDAV también apunta a la API de CalDAV en este sistema
    }

    # --- RUTA PARA LA API (EL TRUCO MÁGICO) ---
    # Cualquier petición que el frontend haga a /api/... será capturada aquí.
    location /api {
        # 'core' es el nombre del servicio de tu backend en docker-compose.
        # Nginx redirigirá la petición a http://core:8000/...
        proxy_pass http://core:8000;

        # Headers importantes para que el backend reciba la información correcta.
        proxy_set_header Host $host;
        # Preferir CF-Connecting-IP si existe (Cloudflare), si no usar remote_addr
        proxy_set_header X-Real-IP $http_cf_connecting_ip;
        # Si CF-Connecting-IP está vacío, usar remote_addr (fallback para acceso directo)
        if ($http_cf_connecting_ip = "") {
            set $real_ip $remote_addr;
        }
        if ($http_cf_connecting_ip != "") {
            set $real_ip $http_cf_connecting_ip;
        }
        # Nota: La lógica anterior con 'if' dentro de location es limitada en nginx puro sin variables,
        # pero para proxy_set_header podemos pasar ambos y que el backend decida, o usar map en http block.
        # Simplificación para compatibilidad: pasar ambos.

        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header CF-Connecting-IP $http_cf_connecting_ip;
        proxy_set_header CF-Ray $http_cf_ray;

        # Timeouts aumentados para operaciones largas del LLM (15 minutos)
        proxy_read_timeout 900s;
        proxy_connect_timeout 900s;
        proxy_send_timeout 900s;

        # Configuración para streaming y respuestas largas
        proxy_buffering off;
        proxy_cache off;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        client_max_body_size 500M;
    }

    # --- RUTA PARA ARCHIVOS MEDIA GENERADOS (PDFs, etc.) ---
    # Delegamos la entrega de archivos media al backend para asegurar que se encuentren los volúmenes.
    location /media/ {
        proxy_pass http://core:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        expires 30d;
        add_header Cache-Control "public";
    }

    # --- RUTA PARA WEBSOCKETS ---
    location /ws {
        proxy_pass http://core:8000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        # Timeout largo para conexiones persistentes
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
        proxy_buffering off;
    }

    # --- RUTA PARA ARCHIVOS ESTÁTICOS DE NEXT.JS ---
    # Sirve directamente los archivos estáticos generados por Next.js.
    # La ruta 'root' debe apuntar al directorio donde se encuentran los archivos estáticos
    # dentro del contenedor de Nginx. Asumimos que se copian desde el build de Next.js.
    location /_next/static/ {
        alias /app/.next/static/; # Asegúrate de que esta ruta sea correcta dentro del contenedor de Nginx
        expires 1y; # Cachear archivos estáticos por un año
        access_log off;
        add_header Cache-Control "public";
    }

    # --- RUTA PARA ONLYOFFICE ---
    # OnlyOffice está corriendo en el host en localhost:8081
    location /onlyoffice/ {
        proxy_pass http://host.docker.internal:8081/;

        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Headers específicos de OnlyOffice
        proxy_set_header X-Forwarded-Host $host;
    }

    # --- RUTA PARA EL FRONTEND ---
    # Todas las demás peticiones (la carga inicial de la página, etc.) irán aquí.
    location / {
        # 'frontend' es el nombre del servicio de tu frontend en docker-compose.
        # Nginx redirigirá la petición a http://frontend:3000
        proxy_pass http://frontend:3000;

        # Headers necesarios para que Next.js funcione correctamente (especialmente para Fast Refresh y WebSockets).
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

